import AutoMobilePrototype
import Foundation
import SwiftUI

/// The embeddingSample prototype, drawn by the AutoMobile prototype renderer. Generated by
/// automobile:prototype/native: the spec and assets live in Prototypes/embeddingSample.
struct EmbeddingSamplePrototype: View {
    var network: PrototypeNetworkConfiguration = .default
    var onEvent: @MainActor (PrototypeEvent) -> Void = { _ in }
    var onDismiss: @MainActor (PrototypeDismissReason) -> Void = { _ in }

    // Read once per process, not on every body evaluation.
    private static let spec = resource("spec.json")
    private static let assets = PrototypeAssets(images: ["hero": resource("hero.png")], fonts: [:])

    var body: some View {
        AutoMobilePrototypeView(
            spec: Self.spec,
            assets: Self.assets,
            storage: .fileBacked,
            network: network,
            onEvent: onEvent,
            onDismiss: onDismiss
        )
    }

    /// Bundled file bytes; a missing spec shows the renderer's load-error view instead of a blank screen.
    private static func resource(_ name: String) -> Data {
        let url = Bundle.main.bundleURL
            .appendingPathComponent("Prototypes/embeddingSample")
            .appendingPathComponent(name)
        return (try? Data(contentsOf: url)) ?? Data()
    }
}
